            database = application "Database" "Stores shipments and dispatch records" "Database"
        }

        emailProvider = softwareSystem "Email Delivery Provider" "An email delivery provider operated by a different organization"

        customer -> webPortal "looks up the status of their parcels"
        dispatchService -> emailProvider "sends customer notification emails through"
        parcelTracker -> database "stores shipments and dispatch records in"
    }
}

